import java.util.*;

class Solution {
    public String removeKdigits(String num, int k) {
        StringBuilder st = new StringBuilder();  // used as an increasing stack
        for (char d : num.toCharArray()) {
            while (k > 0 && st.length() > 0 && st.charAt(st.length() - 1) > d) {
                st.deleteCharAt(st.length() - 1);  // a bigger digit before a smaller one: drop it
                k--;
            }
            st.append(d);
        }
        st.setLength(st.length() - k);           // leftover deletions come off the end
        int i = 0;
        while (i < st.length() && st.charAt(i) == '0') i++;  // strip leading zeros
        String res = st.substring(i);
        return res.isEmpty() ? "0" : res;
    }
}

