function removeKdigits(num, k) {
  // pick len-k digits: each time choose the smallest digit in the allowed window (leftmost)
  const n = num.length, keep = n - k; let out = "", start = 0;
  for (let r = 0; r < keep; r++) {
    const end = n - (keep - r); let best = start;
    for (let i = start + 1; i <= end; i++) { if (num[i] < num[best]) { best = i; if (num[i] === "0") break; } }
    out += num[best]; start = best + 1;
  }
  out = out.replace(/^0+/, "");
  return out === "" ? "0" : out;
}
